# Long-form versions of the articles live in articles_data/<key>.py (ARTICLE + optional NEW_SRC).
# When a file exists it replaces the shorter copy above.
def _load_long_form():
    import os
    import runpy
    folder = os.path.join(os.path.dirname(os.path.abspath(__file__)), "articles_data")
    for key in list(ARTICLE_CONTENT):
        path = os.path.join(folder, key + ".py")
        if os.path.exists(path):
            data = runpy.run_path(path)
            ARTICLE_CONTENT[key] = data["ARTICLE"]
            for src_key, value in data.get("NEW_SRC", {}).items():
                SRC.setdefault(src_key, value)


_load_long_form()
